"""Numerical comparison: collapsing vs. separating size ladders."""
from __future__ import annotations
from typing import Callable, Optional


def is_poly_bounded_witness(f: Callable[[int], int], n_max: int = 30,
                            k_max: int = 12) -> Optional[int]:
    """Least k with f(n)+1 <= (n+2)**k on [0, n_max], else None."""
    for k in range(k_max + 1):
        if all(f(n) + 1 <= (n + 2) ** k for n in range(n_max + 1)):
            return k
    return None


def simulates(a: Callable[[int], int], b: Callable[[int], int],
              n_max: int = 12, k_max: int = 12) -> Optional[int]:
    """Domination-law test: least k with a(n)+1 <= (b(n)+2)**k, else None."""
    for k in range(k_max + 1):
        if all(a(n) + 1 <= (b(n) + 2) ** k for n in range(n_max + 1)):
            return k
    return None


def collapsing(k: int) -> Callable[[int], int]:
    return lambda n: 2 ** (k * n)


def separating(k: int) -> Callable[[int], int]:
    return lambda n: 2 ** (n ** k)


if __name__ == "__main__":
    print("Exponential ladder 2^(k*n): consecutive rungs mutually simulate")
    for k in (1, 2, 3):
        up = simulates(collapsing(k), collapsing(k + 1), n_max=6)
        dn = simulates(collapsing(k + 1), collapsing(k), n_max=6)
        print(f"  k={k}: up={up}, down={dn} -> p-equivalent (collapse)")
    print("Power ladder 2^(n^k): faster CANNOT simulate slower")
    for k in (1, 2):
        # the slower 2^(n^k) is dominated by an identity blow-up of 2^(n^(k+1))
        up = simulates(separating(k), separating(k + 1), n_max=6)
        print(f"  k={k}: slower-simulates-faster={up}; strict separation upward")

"""The direct-sum meet: max of two polynomial blow-ups stays polynomial."""
from __future__ import annotations
from typing import Callable, Optional


def is_poly_bounded_witness(f: Callable[[int], int], n_max: int = 40,
                            k_max: int = 16) -> Optional[int]:
    for k in range(k_max + 1):
        if all(f(n) + 1 <= (n + 2) ** k for n in range(n_max + 1)):
            return k
    return None


def poly_max(f: Callable[[int], int],
             g: Callable[[int], int]) -> Callable[[int], int]:
    return lambda n: max(f(n), g(n))


if __name__ == "__main__":
    examples = [
        (lambda n: 3 * n + 5, lambda n: n * n, "3n+5", "n^2"),
        (lambda n: n ** 3, lambda n: 7 * n + 2, "n^3", "7n+2"),
    ]
    for f, g, fn, gn in examples:
        kf = is_poly_bounded_witness(f)
        kg = is_poly_bounded_witness(g)
        kh = is_poly_bounded_witness(poly_max(f, g))
        print(f"max({fn},{gn}) blow-up witness k={kh} <= {kf}+{kg}+1={kf+kg+1}")
    print("=> R simulating P and Q simulates P(+)Q: binary meets exist.")

