function witnessed_domination(a, b, n_max, k_max):
    for k = 0 to k_max:
        ok = true
        for n = 0 to n_max:
            if a(n) + 1 > (b(n) + 2)^k:
                ok = false; break
        if ok: return k          # certificate of simulation
    return None                  # no polynomial blow-up of degree <= k_max
